#define TEAM_RL_POLICY_OBS_SIZE 89
#define TEAM_RL_POLICY_ACTION_SIZE 5
/* Move-target/cast-flag bounds -- must match the training env's own
 * MOVE_TARGET_RANGE and action_space definition exactly. PPO's own action_net
 * is a plain unconstrained Linear layer (no output activation), so the raw
 * forward pass alone does not guarantee in-range values -- this wrapper clips.
 * KNOWN GAP (found 2026-08-11, not fixed here): this 20.0f is hardcoded
 * regardless of which model is actually being exported -- correct for
 * scripts/rl_env.py's own 1v1 MOVE_TARGET_RANGE, but scripts/rl_env_team.py's
 * own team-mode action space is scaled to ARENA_HALF_EXTENT (~51.78) instead,
 * not this value. A caller that treats the raw output as a literal world-space
 * target (like rl_engage_nudge's own 1v1 usage) would get a real, silently
 * wrong clip range for a team-mode export -- a caller that only reads the
 * output's DIRECTION (normalizing before use, like team_rl_engage_nudge's own
 * apps/arena_bot/src/main.c usage) is unaffected by this gap. Real fix needs
 * the actual range threaded through from whichever training script is
 * exporting, not attempted in this pass.
 */
#define TEAM_RL_POLICY_MOVE_TARGET_RANGE 20.0f

/* team_rl_policy_forward: runs the policy network and clips the raw
 * action-mean output to the real action-space bounds -- out_action must be
 * preallocated to TEAM_RL_POLICY_ACTION_SIZE floats. */
static inline void team_rl_policy_forward(const float *obs, float *out_action) {
    mlp_forward(&RL_POLICY_TEAM_MODEL, obs, out_action);
    if (out_action[0] < -TEAM_RL_POLICY_MOVE_TARGET_RANGE) out_action[0] = -TEAM_RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[0] >  TEAM_RL_POLICY_MOVE_TARGET_RANGE) out_action[0] =  TEAM_RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[1] < -TEAM_RL_POLICY_MOVE_TARGET_RANGE) out_action[1] = -TEAM_RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[1] >  TEAM_RL_POLICY_MOVE_TARGET_RANGE) out_action[1] =  TEAM_RL_POLICY_MOVE_TARGET_RANGE;
    for (int i = 2; i < TEAM_RL_POLICY_ACTION_SIZE; i++) {
        if (out_action[i] < -1.0f) out_action[i] = -1.0f;
        if (out_action[i] >  1.0f) out_action[i] =  1.0f;
    }
}

